// Valida la firma HMAC-SHA256 que manda la app en X-Turnos-Signature.
// El secreto debe coincidir con N8N_WEBHOOK_SECRET del proyecto Next.js.
// Guardalo en n8n como variable de entorno TURNOS_WEBHOOK_SECRET.
const crypto = require('crypto');

const secreto = $env.TURNOS_WEBHOOK_SECRET || '';
const entrada = $input.first();
const firmaRecibida = entrada.json.headers['x-turnos-signature'] || '';
const cuerpo = entrada.json.body;

if (!secreto) {
  throw new Error('Falta la variable de entorno TURNOS_WEBHOOK_SECRET en n8n');
}

// Importante: hay que firmar el JSON EXACTO que mando la app.
// Por eso el nodo Webhook tiene rawBody activado.
const crudo = entrada.binary?.data
  ? Buffer.from(entrada.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(cuerpo);

const esperada = crypto.createHmac('sha256', secreto).update(crudo).digest('hex');

const iguales =
  firmaRecibida.length === esperada.length &&
  crypto.timingSafeEqual(Buffer.from(firmaRecibida), Buffer.from(esperada));

if (!iguales) {
  throw new Error('Firma invalida: la peticion no viene de la app de Turnos');
}

return [{ json: cuerpo }];

const d = $json.data;
const texto =
  'Hola ' + d.client.name + ', cancelamos tu turno del ' + d.display.date +
  ' a las ' + d.display.time + ' en ' + d.business.name + '.' +
  (d.booking.cancellationReason ? '\nMotivo: ' + d.booking.cancellationReason : '') +
  '\n\nCuando quieras podes sacar uno nuevo. Te esperamos!';

return [{ json: {
  para_whatsapp: d.client.phone,
  para_email: d.client.email,
  asunto: 'Turno cancelado — ' + d.business.name,
  // Aviso interno para el profesional, para que libere la agenda
  aviso_profesional: d.professional.email,
  texto,
  original: $json,
} }];
